const body = $input.first().json.body || $input.first().json;
const toolCallList = body?.message?.toolCallList || [];
const toolCall = toolCallList[0] || {};
const toolCallId = toolCall.id || 'unknown';
let args = {};
try { args = JSON.parse(toolCall.function?.arguments || '{}'); } catch(e) { args = {}; }
return [{ json: { toolCallId, phone: args.phone || '', newDate: args.newDate || '', newTime: args.newTime || '', doctorName: args.doctorName || '' } }];

const toolCallId = $('Argümanları Çıkar').first().json.toolCallId;
const newDate = $('Argümanları Çıkar').first().json.newDate;
const newTime = $('Argümanları Çıkar').first().json.newTime;
const updated = $('Randevu Güncelle').all().map(i => i.json).filter(r => r.id);
if (updated.length === 0) {
  return [{ json: { toolCallId, result: 'Güncellenecek aktif randevunuz bulunamadı. Lütfen telefon numaranızı kontrol edin.' } }];
}
return [{ json: { toolCallId, result: `Randevunuz ${newDate} tarihinde saat ${newTime} olarak yeniden planlandı. Onaylıyor musunuz?` } }];
